INSERT INTO ropa.template_sets (id, name, set_type, industry, status, published_at) VALUES
    ('00000000-0000-7000-8000-000000000017', 'ชุดกิจกรรมสำหรับผู้ควบคุมข้อมูลภาครัฐ ตามแม่แบบ สพร. v1.0 (2564)', 'government', NULL, 'published', now());

INSERT INTO ropa.activity_templates (template_set_id, code, name_th, name_en, job_category, role, defaults, rationale, legal_refs) VALUES
    ('00000000-0000-7000-8000-000000000017', 'gov_dga_procurement', 'จัดซื้อจัดจ้างและบริหารสัญญาภาครัฐ', 'Government procurement and contract management', 'procurement', 'controller', '{"description_th": "เก็บข้อมูลผู้เสนองานและคู่สัญญาเพื่อดำเนินการจัดซื้อจัดจ้างตามระเบียบราชการ", "description_en": "Collect bidder and contractor data to conduct procurement under government regulations", "purposes": [{"purpose_text_th": "ปฏิบัติภารกิจจัดซื้อจัดจ้างตามระเบียบของหน่วยงานรัฐ", "purpose_text_en": "Performing procurement duties under government regulations", "lawful_basis_code": "PUBLIC_TASK"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "financial", "subject_type_code": "customer", "source": "direct"}], "recipients": [{"recipient_role": "controller", "note_th": "หน่วยงานตรวจสอบของรัฐ (เช่น สตง.)"}], "retention": [{"retention_months": 120, "retention_basis_th": "เก็บตามระเบียบการเก็บเอกสารราชการด้านการเงินและการจัดซื้อจัดจ้าง", "trigger_event_th": "ครบรอบการทบทวนเอกสารราชการตามระเบียบ", "disposal_method": "delete"}], "security_controls": ["AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับภารกิจตามกฎหมายของหน่วยงานภาครัฐสำหรับกิจกรรม \"จัดซื้อจัดจ้างและบริหารสัญญาภาครัฐ\" ตามแม่แบบ สพร. v1.0 (2564)", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของหน่วยงานภาครัฐ โปรดปรับตามระเบียบเก็บเอกสารราชการของแต่ละหน่วยงาน", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงตามแม่แบบ สพร. v1.0 (2564) ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)']),
    ('00000000-0000-7000-8000-000000000017', 'gov_dga_personnel_records', 'บริหารงานบุคคลและบันทึกข้าราชการ/พนักงาน', 'Public-sector personnel records management', 'hr_personnel', 'controller', '{"description_th": "เก็บและบริหารข้อมูลบุคลากรของหน่วยงานรัฐ รวมถึงประวัติการรับราชการและสวัสดิการ", "description_en": "Collect and manage public employee data, including service history and benefits", "purposes": [{"purpose_text_th": "บริหารงานบุคคลตามภารกิจและกฎหมายว่าด้วยระเบียบข้าราชการ", "purpose_text_en": "Managing personnel under the agency''s mandate and civil-service law", "lawful_basis_code": "LEGAL_OBLIGATION"}], "data": [{"data_category_code": "identity", "subject_type_code": "employee", "source": "direct"}, {"data_category_code": "national_id", "subject_type_code": "employee", "source": "direct"}, {"data_category_code": "financial", "subject_type_code": "employee", "source": "direct"}], "recipients": [{"recipient_role": "controller", "note_th": "หน่วยงานกลางด้านบุคลากรภาครัฐ (เช่น สำนักงาน ก.พ.)"}], "retention": [{"retention_months": 360, "retention_basis_th": "เก็บตลอดระยะเวลารับราชการและตามระเบียบเก็บเอกสารประวัติบุคลากรภาครัฐ", "trigger_event_th": "วันที่พ้นจากราชการและครบรอบทบทวนเอกสารตามระเบียบ", "disposal_method": "delete"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับภารกิจตามกฎหมายของหน่วยงานภาครัฐสำหรับกิจกรรม \"บริหารงานบุคคลและบันทึกข้าราชการ/พนักงาน\" ตามแม่แบบ สพร. v1.0 (2564)", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของหน่วยงานภาครัฐ โปรดปรับตามระเบียบเก็บเอกสารราชการของแต่ละหน่วยงาน", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงตามแม่แบบ สพร. v1.0 (2564) ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)','ม.39(5)']),
    ('00000000-0000-7000-8000-000000000017', 'gov_dga_foia_complaint', 'รับเรื่องร้องเรียนและคำขอข้อมูลข่าวสารตาม พ.ร.บ. ข้อมูลข่าวสาร', 'Freedom-of-information request and complaint handling', 'foia_complaint', 'controller', '{"description_th": "รับและดำเนินการคำขอข้อมูลข่าวสารและเรื่องร้องเรียนของประชาชนตามกฎหมายข้อมูลข่าวสารของราชการ", "description_en": "Receive and process freedom-of-information requests and public complaints under the Official Information Act", "purposes": [{"purpose_text_th": "ปฏิบัติตามกฎหมายข้อมูลข่าวสารของราชการและภารกิจรับเรื่องร้องเรียน", "purpose_text_en": "Compliance with the Official Information Act and complaint-handling duties", "lawful_basis_code": "LEGAL_OBLIGATION"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "contact", "subject_type_code": "customer", "source": "direct"}], "recipients": [], "retention": [{"retention_months": 60, "retention_basis_th": "เก็บตามระเบียบการเก็บเอกสารราชการด้านเรื่องร้องเรียน", "trigger_event_th": "ครบรอบการทบทวนเอกสารราชการตามระเบียบ", "disposal_method": "delete"}], "security_controls": ["AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับภารกิจตามกฎหมายของหน่วยงานภาครัฐสำหรับกิจกรรม \"รับเรื่องร้องเรียนและคำขอข้อมูลข่าวสารตาม พ.ร.บ. ข้อมูลข่าวสาร\" ตามแม่แบบ สพร. v1.0 (2564)", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของหน่วยงานภาครัฐ โปรดปรับตามระเบียบเก็บเอกสารราชการของแต่ละหน่วยงาน", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงตามแม่แบบ สพร. v1.0 (2564) ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)']);

